sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float strength;
uniform float radius;

half4 main(float2 coord) {
    float2 centerPx = center * size;
    float2 d = coord - centerPx;
    float dist = length(d);
    float2 dir = d / max(dist, 0.0001);
    float radiusPx = radius * min(size.x, size.y);
    float t = smoothstep(radiusPx, 0.0, dist);
    float effect = 1.0 - strength * t;
    float2 sampleCoord = centerPx + dir * (dist * effect);
    half4 color = image.eval(sampleCoord);
    if (color.a > 0.001) {
        color.rgb /= color.a;
    }
    return half4(color.rgb * color.a, color.a);
}
